syntax:
class Singleton {
  private static instance: Singleton
  static getInstance() { ... }
}

example:
class ConexaoBanco {
  private static instance: ConexaoBanco
  private constructor() {}
  static getInstance() {
    if (!ConexaoBanco.instance) {
      ConexaoBanco.instance = new ConexaoBanco()
    }
    return ConexaoBanco.instance
  }
}

