syntax:
class Proxy implements Interface {
  constructor(private real: Interface) {}
  operacao() { /* lógica extra */ return this.real.operacao() }
}

example:
class ImagemProxy implements Imagem {
  private real: ImagemReal | null = null
  constructor(private caminho: string) {}
  exibir() {
    if (!this.real) this.real = new ImagemReal(this.caminho)
    this.real.exibir()
  }
}

syntax:
interface Componente { renderizar(): string }
class Composto implements Componente {
  filhos: Componente[] = []
  renderizar() { return this.filhos.map((f) => f.renderizar()).join() }
}

example:
interface ItemMenu { calcularPreco(): number }
class Prato implements ItemMenu {
  constructor(private preco: number) {}
  calcularPreco() { return this.preco }
}
class Combo implements ItemMenu {
  private itens: ItemMenu[] = []
  adicionar(item: ItemMenu) { this.itens.push(item) }
  calcularPreco() { return this.itens.reduce((s, i) => s + i.calcularPreco(), 0) }
}

syntax:
abstract class Handler {
  private proximo: Handler
  setProximo(h: Handler) { this.proximo = h; return h }
  tratar(req) { return this.proximo?.tratar(req) }
}

example:
class ValidacaoHandler extends Handler {
  tratar(req) {
    if (!req.valido) return "Requisição inválida"
    return super.tratar(req)
  }
}
class AutenticacaoHandler extends Handler {
  tratar(req) {
    if (!req.autenticado) return "Não autenticado"
    return super.tratar(req)
  }
}

