syntax:
interface Iterador<T> {
  temProximo(): boolean
  proximo(): T
}

example:
class ColecaoPersonalizada implements Iterable<number> {
  private itens = [1, 2, 3]
  [Symbol.iterator]() {
    let i = 0
    return {
      next: () => i < this.itens.length
        ? { value: this.itens[i++], done: false }
        : { value: undefined, done: true }
    }
  }
}
for (const item of new ColecaoPersonalizada()) { console.log(item) }

